// LTO removes this entire function body
// if no call site is found across all linked objects.
static int dead_code_section() {
    // Complex, heavy computation avoided
    return 100 * 1000;
}

// External reference point
void application_start(int input) {
    if (input > 0) {
        // Only active code remains
        int result = input + 1;
    }
    // dead_code_section() is never invoked.
}

